mapper.select:
select T.PERIOD_ as KEY_, count(*) as COUNT_, 0 as EXTRA_
from (
  select ${periodOfStartSql} as PERIOD_
  from ${prefix}ACT_HI_PROCINST P
  where 
    and P.START_TIME_ >= #{periodStart} and P.START_TIME_ < #{periodEnd}
) T
group by T.PERIOD_

select N.TASK_DEF_KEY_, N.NAME_, N.ASSIGNEE_, N.START_TIME_, N.END_TIME_, (select min(L.TIMESTAMP_) from ${prefix}ACT_HI_IDENTITYLINK L where L.TASK_ID_ = N.ID_ and L.TYPE_ = 'assignee' and L.OPERATION_TYPE_ = 'add') as FIRST_ASSIGN_ from (
select T.ID_, T.TASK_DEF_KEY_, T.NAME_, T.ASSIGNEE_, T.START_TIME_, T.END_TIME_ from ${prefix}ACT_HI_TASKINST T where and T.END_TIME_ >= #{after} and T.END_TIME_ < #{before} and T.DELETE_REASON_ = 'completed' order by T.END_TIME_ desc, T.ID_
) N
